const roles = [
  'Project Manager',
  'Senior Project Manager',
  'Technical Project Manager',
  'Product Owner',
  'Technical Product Owner',
  'Product Manager',
  'Scrum Master',
  'Delivery Manager',
  'Implementation Manager',
  'Program Manager',
  'Agile roles',
  'AI Project Manager',
  'AI Product Manager',
  'AI Project/Product roles'
];
const locations = [
  'Canada',
  'Colombia',
  'Argentina',
  'Mexico',
  'Chile',
  'Peru',
  'Spain',
  'LATAM',
  'Worldwide Remote',
  'remote Canada allowed',
  'remote from Canada'
];
const portals = [
  { source: 'LinkedIn Jobs', site: 'site:linkedin.com/jobs/view' },
  { source: 'Indeed', site: 'site:indeed.com/viewjob OR site:ca.indeed.com/viewjob OR site:mx.indeed.com/viewjob OR site:co.indeed.com/viewjob OR site:ar.indeed.com/viewjob OR site:cl.indeed.com/viewjob OR site:pe.indeed.com/viewjob OR site:es.indeed.com/viewjob' },
  { source: 'Greenhouse', site: 'site:boards.greenhouse.io' },
  { source: 'Lever', site: 'site:jobs.lever.co' },
  { source: 'Workable', site: 'site:apply.workable.com' },
  { source: 'Ashby', site: 'site:jobs.ashbyhq.com' },
  { source: 'GetOnBoard', site: 'site:getonbrd.com/jobs OR site:getonboard.com/jobs' },
  { source: 'Torre', site: 'site:torre.ai/jobs OR site:torre.co/jobs' },
  { source: 'Company Careers', site: '(careers OR jobs OR greenhouse OR lever OR ashby OR workable)' },
  { source: 'Google Web Index', site: '(remote OR remoto OR hybrid OR hibrido OR job OR empleo OR vacancy OR vacante)' }
];
const output = [];
for (const role of roles) {
  for (const location of locations) {
    for (const portal of portals) {
      output.push({
        json: {
          query: portal.site + ' "' + role + '" "' + location + '" (remote OR remoto OR "work from home" OR "trabajo remoto") -internship -practicante',
          role,
          location,
          source_hint: portal.source,
          searched: 1
        }
      });
    }
  }
}
return output;

function asArray(value) {
  if (Array.isArray(value)) return value;
  if (!value || typeof value !== 'object') return [];
  return value.results || value.items || value.organic_results || value.webPages?.value || value.data || [];
}
function pick(obj, keys) {
  for (const key of keys) {
    if (obj && obj[key] !== undefined && obj[key] !== null && String(obj[key]).trim() !== '') return String(obj[key]).trim();
  }
  return '';
}
const seen = new Set();
const out = [];
for (const item of items) {
  const raw = item.json.search_raw || item.json.body || item.json;
  for (const result of asArray(raw)) {
    const url = pick(result, ['url','link','href','job_url','apply_url']);
    if (!url) continue;
    let normalizedUrl;
    try {
      const parsed = new URL(url);
      parsed.hash = '';
      normalizedUrl = parsed.toString();
    } catch {
      continue;
    }
    if (seen.has(normalizedUrl)) continue;
    seen.add(normalizedUrl);
    out.push({ json: {
      title: pick(result, ['title','name','job_title']) || 'Unknown title',
      company: pick(result, ['company','company_name','organization']) || 'Unknown company',
      url: normalizedUrl,
      source: item.json.source_hint || pick(result, ['source','displayLink','site','engine']) || new URL(normalizedUrl).hostname,
      location: pick(result, ['location','job_location','formattedLocation']) || item.json.location || '',
      snippet: pick(result, ['snippet','description','summary','content']) || ''
    }});
  }
}
return out;

function htmlToText(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}
const out = [];
for (const item of items) {
  const job = { ...item.json };
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 25000);
    const response = await fetch(job.url, { signal: controller.signal, headers: { 'User-Agent': 'BOTZ Job Hunter n8n workflow' } });
    clearTimeout(timeout);
    const body = await response.text();
    const text = htmlToText(body);
    job.full_job_text = text;
    job.extraction_status = response.ok && text.length >= 1200 ? 'OK' : 'NEEDS_REVIEW';
    if (!response.ok) job.extraction_error = `HTTP ${response.status}`;
  } catch (error) {
    job.full_job_text = '';
    job.extraction_status = 'NEEDS_REVIEW';
    job.extraction_error = error.message;
  }
  out.push({ json: job });
}
return out;

const englishTerms = [
  /\benglish\b/i, /fluent\s+english/i, /advanced\s+english/i, /professional\s+english/i, /business\s+english/i, /english\s+proficiency/i, /\bbilingual\b/i, /\bA1\b/i, /\bA2\b/i, /\bB1\b/i, /\bB2\b/i, /\bC1\b/i, /\bC2\b/i
];
const negatedNoEnglish = /\b(no|not|without|sin|no se requiere|no requiere|não requer)\b.{0,30}\benglish|ingl[eé]s\b/i;
const out = [];
for (const item of items) {
  const job = { ...item.json };
  const text = String(job.full_job_text || '');
  const lower = text.toLowerCase();
  const evidence = [];
  for (const pattern of englishTerms) {
    const match = text.match(pattern);
    if (!match) continue;
    const index = Math.max(0, match.index - 120);
    const excerpt = text.slice(index, Math.min(text.length, match.index + 180));
    if (/no english required|english not required|sin ingl[eé]s|no requiere ingl[eé]s/i.test(excerpt)) continue;
    evidence.push(excerpt.trim());
  }
  const fullChecked = job.extraction_status === 'OK' && text.length >= 1200;
  job.english_prefilter_evidence = evidence;
  job.english_required = evidence.length > 0;
  job.english_preferred = /english.{0,40}(preferred|nice to have|deseable|preferido)|(?:preferred|deseable|preferido).{0,40}english/i.test(text);
  job.bilingual_required = /\bbilingual\b|biling[uü]e/i.test(text) && !negatedNoEnglish.test(text);
  job.english_level_found = (text.match(/\b(A1|A2|B1|B2|C1|C2)\b.{0,50}(english|ingl[eé]s)|(?:english|ingl[eé]s).{0,50}\b(A1|A2|B1|B2|C1|C2)\b/i) || [null])[0];
  if (!fullChecked) {
    job.prefilter_decision = 'NEEDS_REVIEW';
  } else if (evidence.length || job.english_preferred || job.bilingual_required || job.english_level_found) {
    job.prefilter_decision = 'REJECT';
  } else {
    job.prefilter_decision = 'CONTINUE';
  }
  job.english_certification = {
    status: job.prefilter_decision === 'REJECT' ? 'ENGLISH_FOUND' : 'UNVERIFIED',
    full_description_checked: fullChecked,
    english_required: Boolean(job.english_required),
    english_preferred: Boolean(job.english_preferred),
    bilingual_required: Boolean(job.bilingual_required),
    english_level_found: job.english_level_found || null,
    evidence,
    validator_1: null,
    validator_2: null
  };
  out.push({ json: job });
}
return out;

function responseOf(item) {
  const j = item.json;
  return j.validator_1_raw || j.output || j.response || j.body || j;
}
function parseMaybe(value) {
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return { decision: 'FAIL', reason: value }; }
  }
  return value || {};
}
return items.map(item => {
  const job = { ...item.json };
  const raw = parseMaybe(responseOf(item));
  const candidate = raw.decision ? raw : raw.output || raw.result || raw.response || raw.content || {};
  job.validator_1 = parseMaybe(candidate);
  job.english_certification = job.english_certification || {};
  job.english_certification.validator_1 = job.validator_1.decision || 'FAIL';
  return { json: job };
});

function parseMaybe(value) {
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return { decision: 'FAIL', reason: value }; }
  }
  return value || {};
}
function unwrap(value) {
  const raw = parseMaybe(value);
  return raw.decision ? raw : parseMaybe(raw.output || raw.result || raw.response || raw.content || raw.body || raw);
}
return items.map(item => {
  const job = { ...item.json };
  const v1 = unwrap(job.validator_1);
  const v2 = unwrap(job.validator_2_raw || job.output || job.response || job.body);
  const c1 = v1.english_certification || {};
  const c2 = v2.english_certification || {};
  const fullChecked = c1.full_description_checked === true && c2.full_description_checked === true && job.extraction_status === 'OK';
  const noEnglish = c1.status === 'CERTIFIED_NO_ENGLISH' && c2.status === 'CERTIFIED_NO_ENGLISH' &&
    c1.english_required === false && c2.english_required === false &&
    c1.english_preferred === false && c2.english_preferred === false &&
    c1.bilingual_required === false && c2.bilingual_required === false &&
    !c1.english_level_found && !c2.english_level_found;
  const validatorsAgree = v1.decision === v2.decision;
  const passCore = v1.decision === 'PASS' && v2.decision === 'PASS' &&
    v1.english_required === false && v2.english_required === false &&
    v1.canada_allowed === true && v2.canada_allowed === true &&
    v1.remote === true && v2.remote === true &&
    v1.active === true && v2.active === true &&
    Number(v1.role_match || 0) >= 75 && Number(v2.role_match || 0) >= 75;
  const certifiedReady = passCore && fullChecked && noEnglish && validatorsAgree;
  job.validator_1 = v1;
  job.validator_2 = v2;
  job.english_required = Boolean(v1.english_required || v2.english_required || !noEnglish);
  job.english_preferred = Boolean(c1.english_preferred || c2.english_preferred);
  job.bilingual_required = Boolean(c1.bilingual_required || c2.bilingual_required);
  job.canada_allowed = v1.canada_allowed === true && v2.canada_allowed === true;
  job.remote = v1.remote === true && v2.remote === true;
  job.active = v1.active === true && v2.active === true;
  job.role_match = Math.min(Number(v1.role_match || 0), Number(v2.role_match || 0));
  job.decision = certifiedReady ? 'PASS' : (validatorsAgree ? 'FAIL' : 'NEEDS_REVIEW');
  job.validation_reason = certifiedReady ? 'Passed both validators with certified no-English requirement' : (!validatorsAgree ? 'Validators did not agree' : (v1.reason || v2.reason || 'Fail-closed validation failed'));
  job.validation_evidence = [...(Array.isArray(v1.evidence) ? v1.evidence : []), ...(Array.isArray(v2.evidence) ? v2.evidence : []), ...(Array.isArray(c1.evidence) ? c1.evidence : []), ...(Array.isArray(c2.evidence) ? c2.evidence : [])];
  job.english_certification = {
    status: certifiedReady ? 'CERTIFIED_NO_ENGLISH' : ((c1.status === 'ENGLISH_FOUND' || c2.status === 'ENGLISH_FOUND') ? 'ENGLISH_FOUND' : 'UNVERIFIED'),
    full_description_checked: fullChecked,
    english_required: Boolean(v1.english_required || v2.english_required || c1.english_required || c2.english_required),
    english_preferred: Boolean(c1.english_preferred || c2.english_preferred),
    bilingual_required: Boolean(c1.bilingual_required || c2.bilingual_required),
    english_level_found: c1.english_level_found || c2.english_level_found || null,
    evidence: job.validation_evidence,
    validator_1: v1.decision || 'FAIL',
    validator_2: v2.decision || 'FAIL'
  };
  job.status = certifiedReady ? 'READY_TO_APPLY' : (job.english_certification.status === 'ENGLISH_FOUND' ? 'REJECTED' : 'NEEDS_REVIEW');
  return { json: job };
});

const report = { searched: items.length, new_jobs: items.length, rejected: 0, validated: 0, ready_to_apply: 0, needs_review: 0, errors: 0 };
for (const item of items) {
  const status = item.json.status;
  if (status === 'REJECTED') report.rejected += 1;
  if (status === 'VALIDATED') report.validated += 1;
  if (status === 'READY_TO_APPLY') { report.ready_to_apply += 1; report.validated += 1; }
  if (status === 'NEEDS_REVIEW') report.needs_review += 1;
  if (status === 'ERROR' || item.json.error || item.json.extraction_error) report.errors += 1;
}
return [{ json: report }];
